css:
.d-sequential-task-runner{width:100%;max-width:430px;min-width:0;color:var(--ink);font:inherit;font-size:14px;line-height:1.5;overflow-wrap:anywhere}
.d-sequential-task-runner *,.d-sequential-task-runner *::before,.d-sequential-task-runner *::after{box-sizing:border-box}
.d-sequential-task-runner [hidden]{display:none!important}
.d-sequential-task-runner .d-row{display:flex;flex-wrap:wrap;align-items:center;gap:8px;margin:8px 0}
.d-sequential-task-runner .d-note{display:block;margin:8px 0 0;color:var(--muted);font-size:12px;min-height:1.5em}
.d-sequential-task-runner label{display:block;margin:8px 0}
.d-sequential-task-runner input,.d-sequential-task-runner select,.d-sequential-task-runner textarea,.d-sequential-task-runner button{font:inherit;color:inherit;max-width:100%;min-width:0}
.d-sequential-task-runner input:not([type=checkbox]):not([type=radio]),.d-sequential-task-runner select,.d-sequential-task-runner textarea{width:100%;padding:8px;border:1px solid var(--line);border-radius:var(--radius-control);background:var(--paper)}
.d-sequential-task-runner button{padding:6px 10px;border:1px solid var(--line);border-radius:var(--radius-control);background:var(--paper);cursor:pointer}
.d-sequential-task-runner button:disabled{opacity:.5;cursor:default}
.d-sequential-task-runner :focus-visible{outline:2px solid var(--ink);outline-offset:3px}
.d-sequential-task-runner [aria-invalid=true]{border-color:var(--warn)!important}
.d-sequential-task-runner .d-scroll{max-width:100%;overflow:auto}
.d-sequential-task-runner table{width:100%;border-collapse:collapse;font-size:12px;text-align:left}
.d-sequential-task-runner th,.d-sequential-task-runner td{padding:7px;border-bottom:1px solid var(--line);vertical-align:top}
.d-sequential-task-runner caption{text-align:left;font-weight:600;margin-bottom:8px}
.d-sequential-task-runner progress{width:100%;accent-color:var(--ink)}
.d-sequential-task-runner pre{white-space:pre-wrap;overflow-wrap:anywhere;font-size:12px}
.d-sequential-task-runner h3,.d-sequential-task-runner p{margin:8px 0}
.d-sequential-task-runner [aria-pressed=true],.d-sequential-task-runner [aria-selected=true]{border-color:var(--ink);font-weight:650}
.d-sequential-task-runner .d-grow{flex:1;min-width:100px}
.d-sequential-task-runner summary{cursor:pointer;padding:6px 0}
.d-sequential-task-runner ul,.d-sequential-task-runner ol{padding-left:24px}

init:
root => {
 const q = selector => root.querySelector(selector);
 const qa = selector => [...root.querySelectorAll(selector)];
 const say = text => { const out = q('[data-out]'); if (out) out.textContent = text; };
 ((root,q,qa,say)=>{let timer=null,index=0,running=false;const names=['检查名称','检查格式','生成清单'];const sync=()=>{q('[data-start]').disabled=running;q('[data-stop]').disabled=!running;};const next=()=>{if(!running)return;qa('[data-list] li')[index].textContent=names[index]+' · 完成';index++;say('已完成 '+index+' / 3 项');if(index===3){running=false;sync();return;}qa('[data-list] li')[index].textContent=names[index]+' · 进行中';timer=setTimeout(next,200);};q('[data-start]').onclick=()=>{index=0;running=true;qa('[data-list] li').forEach((el,i)=>el.textContent=names[i]+' · '+(i?'等待':'进行中'));sync();timer=setTimeout(next,200);say('队列运行中');};q('[data-stop]').onclick=()=>{clearTimeout(timer);running=false;qa('[data-list] li')[index].textContent=names[index]+' · 已停止';sync();say('已停止，保留 '+index+' 项完成结果');};sync();})(root, q, qa, say);
}
